var dueInput = document.querySelector('[data-testid="todo-due"]');
var priorityInput = document.querySelector('[data-testid="todo-priority"]');
var searchInput = document.querySelector('[data-testid="search-input"]');

// [REQ-001]
function makeId() {
  if (window.crypto && typeof window.crypto.randomUUID === 'function') {
    return window.crypto.randomUUID();
  }
  return Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 10);
}

// [REQ-001]
function loadTodos() {
  try {
    var parsed = JSON.parse(localStorage.getItem(STORAGE_KEY));
    return Array.isArray(parsed) ? parsed : [];
  } catch (e) {
    return [];
  }
}

// [REQ-001]
function saveTodos() {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
  } catch (e) {}
}

var todos = loadTodos();
var filter = 'all';
var filterButtons = document.querySelectorAll('[data-filter]');
var search = '';        // [REQ-007]
var editingId = null;   // [REQ-007] id of the todo whose text is being edited
var editDraft = '';
var rendering = false;  // [REQ-007] ignore blur caused by render removing the field

// [REQ-002] Active todos first, then completed.
// [REQ-005] Within each group: high, then med, then low; same priority keeps insertion order.
function orderedTodos() {
  var result = [];
  [false, true].forEach(function (completed) {
    ['high', 'med', 'low'].forEach(function (p) {
      todos.forEach(function (t) {
        if (!!t.completed === completed && normalizePriority(t.priority) === p) result.push(t);
      });
    });
  });
  return result;
}

// [REQ-003] Today's LOCAL calendar date as YYYY-MM-DD (never via UTC).
function todayLocal() {
  var d = new Date();
  var m = d.getMonth() + 1;
  var day = d.getDate();
  return d.getFullYear() + '-' + (m < 10 ? '0' : '') + m + '-' + (day < 10 ? '0' : '') + day;
}

// [REQ-003] Accept only a plain YYYY-MM-DD string; anything else means no due date.
function normalizeDue(value) {
  return typeof value === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(value) ? value : '';
}

// [REQ-003] Overdue = due date strictly before today's local date. Date-only string compare.
function isOverdue(todo, today) {
  var due = normalizeDue(todo.due);
  return due !== '' && due < today;
}

// [REQ-004] Only low, med or high; anything else (including older todos) is med.
function normalizePriority(value) {
  return value === 'low' || value === 'high' ? value : 'med';
}

// [REQ-002]
function isVisible(todo) {
  if (filter === 'active') return !todo.completed;
  if (filter === 'completed') return !!todo.completed;
  return true;
}

// [REQ-007] Case-insensitive substring match; combines with the filter in render.
function matchesSearch(todo) {
  return String(todo.text).toLowerCase().indexOf(search.toLowerCase()) !== -1;
}

